}

/**
 * Reduce a QU cell to comparable digits. The tracker holds 'QU-17902', 'QU- 18006',
 * 'QU-' and 'QU- 17969, 17972, 17973' — string equality is not a usable key across those.
 * Used only for the fallback match; the record id written back to the sheet is the real key.
 */
function normalizeQu(raw) {
  const nums = text(raw).match(/\d{3,}/g);
  return nums ? nums.join(',') : null;
}

/**
 * The same digits as a set. One tracker record can carry several QUs
 * ('QU- 17969, 17972, 17973' is PhilHealth), while its quotation sheet carries one. Joined
 * strings never compare equal across those; sets are compared by overlap instead.
 */
function quSet(raw) {
  return new Set(text(raw).match(/\d{3,}/g) || []);
}

/**
 * @param {Array<Array<string>>} grid  Row-major values of one quotation tab, A1 at [0][0].
 * @param {object} [options]
 * @returns {{fields: object, meta: object, warnings: string[]}}
 */
function extractQuotation(grid, options) {
  const config = Object.assign({}, DEFAULTS, options || {});
  const warnings = [];
  const found = {};

  for (const [key, anchor] of Object.entries(ANCHORS)) {
    const row = findLabelRow(grid, anchor.labels);
    if (row === -1) {
      found[key] = { row: -1, value: '' };
      continue;
    }
    if (row !== anchor.expectedRow - 1) {
      warnings.push(
        `Template drift: '${anchor.labels[0]}' expected on row ${anchor.expectedRow}, found on ` +
          `row ${row + 1}. Read ${address(row, anchor.valueCol)} instead of ` +
          `${address(anchor.expectedRow - 1, anchor.valueCol)}.`
      );
    }
    found[key] = { row, value: meaningful(at(grid, row, anchor.valueCol)) };
  }

  const IDENTITY = ['company', 'contact', 'product', 'services'];
  for (const key of IDENTITY) {
    if (found[key].row === -1) {
      warnings.push(`Missing label '${ANCHORS[key].labels.join("' / '")}' in column A — nothing to read for ${key}.`);
    }
  }
  // A timesheet, a price list, the wrong tab: none of them carry these labels. Three of four
  // is the bar, so one relabelled cell in a real quotation does not stop it syncing.
  const identityLabelsFound = IDENTITY.filter((k) => found[k].row !== -1).length;

  const company = found.company.value;
  const contact = found.contact.value;
  const product = found.product.value;

  // House format, matching the tracker's rows: 'Steve Huang / LAKIWIN'.
  const contactCompany = [contact, company].filter(Boolean).join(' / ');
  // Half a pair is not the whole truth: the LakiWin quote says 'PRODUCER: N/A' while the
  // tracker row reads 'Steve Huang / LAKIWIN'. The sync uses a partial value only to fill a
  // blank field, never to replace one.
  const contactCompanyPartial = Boolean(contactCompany) && (!contact || !company);
  if (!contact || !company) {
    warnings.push(
      `CONTACT Name / COMPANY built from a partial pair (contact='${contact}', company='${company}').`
    );
  }

  const { services, unmatched } = mapServices(found.services.value, config.serviceChoices);
  if (unmatched.length) {
    warnings.push(
      `PROJECT DETAILS has no matching Service choice for: ${unmatched
        .map((u) => `'${u}'`)
        .join(', ')}. Left off the record — add the choice in Airtable or fix the sheet.`
    );
  }

  // Approved cost: the rounded package figure is what the client signs off on. Fall back to
  // TOTAL when it has not been filled in, so the record is never silently zero.
  const rnd = parseMoney(found.rndPackageCost.value);
  const total = parseMoney(found.total.value);
  let approvedCost = rnd;
  let approvedCostSource = 'RND PACKAGE COST';
  if (approvedCost === null) {
    approvedCost = total;
    approvedCostSource = 'TOTAL (fallback)';
    const where =
      found.rndPackageCost.row === -1
        ? 'label not found in column A'
        : `${address(found.rndPackageCost.row, ANCHORS.rndPackageCost.valueCol)} is empty`;
    warnings.push(
      `RND PACKAGE COST: ${where} — used TOTAL instead` +
        (total === null ? ', which is also empty.' : ` (${total}).`)
    );
  }
  if (approvedCost === null) {
    approvedCostSource = 'none';
    warnings.push('No approved cost found — Approved Cost (Local) will be left empty.');
  }

  const qu = extractQuNumber(grid);

  const projectTitle =
    config.projectTitleMode === 'company-product'
      ? [company, product].filter(Boolean).join(' - ')
      : product;

  const fields = {};
  if (projectTitle) fields['Project Title'] = projectTitle;
  if (contactCompany) fields['CONTACT Name / COMPANY'] = contactCompany;
  if (services.length) fields['Service'] = services;
  if (approvedCost !== null) fields['Approved Cost (Local)'] = approvedCost;
  if (qu.quNumber) fields['QU Number'] = qu.quNumber;

  return {
    fields,
    meta: {
      quNumber: qu.quNumber,
      quNumberNormalized: normalizeQu(qu.quNumber),
      quCell: qu.row === -1 ? null : address(qu.row, qu.col),
      approvedCostSource,
      rndPackageCost: rnd,
      total,
      totalNet: parseMoney(found.totalNet.value),
      unmatchedServices: unmatched,
      identityLabelsFound,
      looksLikeQuotation: identityLabelsFound >= 3,
      contactCompanyPartial,
      readFrom: Object.fromEntries(
        Object.entries(found).map(([k, v]) => [
          k,
          v.row === -1 ? null : address(v.row, ANCHORS[k].valueCol),
        ])
      ),
    },
    warnings,
  };
}

/**
 * Decide what a quotation should do to its tracker row: update it, or nothing.
 *
 * Pure. No network. The n8n workflow reads the sheet and the rows that link to it, hands
 * both to decideAction, and performs whatever comes back.
 *
 * The sync never creates rows. Kristine makes each project's row by hand, as she always
 * has, and pastes the quotation's link into its `Quotation Sheet` column. The sync finds
 * the row carrying that link and fills in the typing. That one design choice removes whole
 * classes of failure the earlier create-capable version had to guard against: duplicate
 * rows, junk rows from the wrong spreadsheet, writing a marker back into her files (which
 * are view-only to the sync), and a copied quotation updating the previous client's row —
 * a copy has a different link, so it matches nothing.
 *
 * The rules:
 *
 *  1. Only the row whose `Quotation Sheet` link names this very file is ever touched. No
 *     row, or more than one, and nothing happens.
 *  2. Never write an empty value over a populated one. A blank cell means 'the sheet does
 *     not know', not 'set this to blank'.
 *  3. Never take away what a person put in the tracker. Service tags are only added; an
 *     existing QU is never replaced; Project Title is only filled when blank.
 *  4. If nothing changed, write nothing.
 */


/** The column that ties a tracker row to its quotation. */
const LINK_FIELD = 'Quotation Sheet';

/** Fields the sync fills. Anything else on the row is somebody else's and is left alone. */
const SYNCED_FIELDS = [
  'Project Title',
  'CONTACT Name / COMPANY',
  'Service',
  'Approved Cost (Local)',
  'QU Number',
];

/**
 * Filled only when the row has none. Kristine types her own titles, and they are better
 * than the sheet's PRODUCT cell — 'Haraya Del Rosario - The 90-Day Leadership Field Manual'
 * against 'AUDIOBOOK PRODUCTION - PER DAY RATE'. The sheet's version is only a stand-in
 * for a row she left untitled.
 */
const FILL_IF_BLANK = ['Project Title'];

/** The spreadsheet id inside a pasted link, or the bare id; null for anything else. */
function sheetIdOf(value) {
  const s = String(value === null || value === undefined ? '' : value).trim();
  const m = /\/spreadsheets\/d\/([a-zA-Z0-9_-]{20,})/.exec(s);
  if (m) return m[1];
  return /^[a-zA-Z0-9_-]{20,}$/.test(s) ? s : null;
}

const sameValue = (a, b) => {
  if (Array.isArray(a) || Array.isArray(b)) {
    const x = Array.isArray(a) ? a.slice().sort() : [];
    const y = Array.isArray(b) ? b.slice().sort() : [];
    return x.length === y.length && x.every((v, i) => v === y[i]);
  }
  if (typeof a === 'number' || typeof b === 'number') {
    const x = Number(a);
    const y = Number(b);
    if (Number.isFinite(x) && Number.isFinite(y)) return Math.abs(x - y) < 0.005;
  }
  return String(a === undefined || a === null ? '' : a) === String(b === undefined || b === null ? '' : b);
};

const isEmpty = (v) =>
  v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);

const subsetOf = (a, b) => {
  for (const v of a) if (!b.has(v)) return false;
  return true;
};

const show = (v) => (isEmpty(v) ? '(blank)' : JSON.stringify(v));

/**
 * @param {object} extracted              extractQuotation() output
 * @param {object} options
 * @param {string} options.fileId         the quotation being synced
 * @param {Array}  [options.existingRecords]  [{ id, fields }] — normally only rows whose
 *                                        link mentions this file; re-checked exactly here
 */
function decideAction(extracted, options) {
  const opts = options || {};
  const notes = [];
  const warnings = extracted.warnings || [];
  const incoming = extracted.fields || {};
  const meta = extracted.meta || {};

  const result = (action, extra) =>
    Object.assign({ action, recordId: null, fields: {}, notes, warnings }, extra);

  // The tracker query narrows by substring; this is the exact check.
  const linked = (opts.existingRecords || []).filter(
    (r) => opts.fileId && sheetIdOf(r.fields && r.fields[LINK_FIELD]) === opts.fileId
  );

  if (!linked.length) {
    return result('skip', {
      problem:
        `No tracker row links to this quotation yet. Open the project's row in Airtable, ` +
        `paste this sheet's link into the "${LINK_FIELD}" column, then sync again. ` +
        `Nothing was changed.`,
    });
  }
  if (linked.length > 1) {
    return result('skip', {
      problem:
        `${linked.length} tracker rows link to this quotation ` +
        `(${linked.map((r) => r.id).join(', ')}). Remove the link from the extra row, then ` +
        `sync again. Nothing was changed.`,
    });
  }
  if (!meta.looksLikeQuotation) {
    return result('skip', {
      problem:
        `The linked sheet doesn't look like a quotation — couldn't find the AGENCY/COMPANY, ` +
        `PRODUCER/MAIN CONTACT, PRODUCT and PROJECT DETAILS rows on its MAIN tab. ` +
        `Nothing was changed.`,
    });
  }

  const target = linked[0];
  const current = target.fields || {};
  const sheetQus = quSet(meta.quNumber);
  const fields = {};
  const changes = [];
  const held = [];

  for (const key of SYNCED_FIELDS) {
    const next = incoming[key];
    const now = current[key];

    if (isEmpty(next)) {
      if (!isEmpty(now)) held.push(key);
      continue;
    }

    if (key === 'CONTACT Name / COMPANY' && meta.contactCompanyPartial && !isEmpty(now)) {
      if (!sameValue(next, now)) {
        notes.push(
          `The sheet only has part of the contact/company (${show(next)}), so the tracker's ` +
            `${show(now)} was left as it is.`
        );
      }
      continue;
    }

    if (FILL_IF_BLANK.includes(key)) {
      if (isEmpty(now)) {
        fields[key] = next;
        changes.push(`${key}: ${show(now)} -> ${show(next)}`);
      }
      continue;
    }

    if (key === 'QU Number') {
      // Fill a blank QU — the second sync, after Xero, is exactly this — but never replace
      // one. A record can hold several ('QU- 17969, 17972, 17973'); overwriting would drop
      // the rest, and a QU is an identifier other systems match on.
      const nowQus = quSet(now);
      if (!nowQus.size) {
        fields[key] = next;
        changes.push(`${key}: ${show(now)} -> ${show(next)}`);
      } else if (!subsetOf(sheetQus, nowQus)) {
        notes.push(
          `QU Number differs — sheet says ${show(next)}, tracker says ${show(now)}. Left as ` +
            `it is; an existing QU is never replaced. Change it in Airtable if the sheet is right.`
        );
      }
      continue;
    }

    if (key === 'Service') {
      // Add what the sheet names, never remove what the tracker has: PROJECT DETAILS is a
      // free-text line, and the tags in Airtable were picked by a person.
      const have = Array.isArray(now) ? now.slice() : [];
      const missing = next.filter((s) => !have.includes(s));
      const extra = have.filter((s) => !next.includes(s));
      if (missing.length) {
        fields[key] = have.concat(missing);
        changes.push(`${key}: add ${missing.map((m) => show(m.trim())).join(', ')}`);
      }
      if (extra.length) {
        notes.push(
          `The tracker also has ${extra.map((e) => show(e.trim())).join(', ')} under Service, ` +
            `which the sheet doesn't mention. Kept — remove it in Airtable if it's wrong.`
        );
      }
      continue;
    }

    if (!sameValue(next, now)) {
      fields[key] = next;
      changes.push(`${key}: ${show(now)} -> ${show(next)}`);
    }
  }

  if (held.length) {
    notes.push(`Sheet had nothing for ${held.join(', ')} — left the tracker's values alone.`);
  }

  if (!changes.length) {
    return result('skip', {
      recordId: target.id,
      reason: `Found the linked row (${target.id}); nothing to change.`,
    });
  }

  return result('update', {
    recordId: target.id,
    fields,
    reason: `Found the linked row (${target.id}). Changing: ${changes.join('; ')}.`,
  });
}

/**
 * The glue between n8n's HTTP nodes and the two pure modules.
 *
 * Everything here is still pure — it takes the raw shapes the Google Sheets and Airtable
 * APIs return (errors included: the read nodes fail soft and hand their error payload on)
 * and produces a decision plus the text Kristine sees on the form's final screen. The
 * Code nodes in the workflow are this file, extract.js and sync.js concatenated by
 * scripts/build-workflow.js. The code that is tested is the code that ships.
 */



// --- link parsing (sliced out verbatim into the Parse Request node) ---------

/**
 * Google URLs all carry a `/d/<id>` segment, so matching that alone accepts a Doc, a
 * deck or an uploaded file just as happily as a spreadsheet. It then fails much later,
 * at the Sheets API, as "Requested entity was not found". Someone pasted a Google Doc link
 * on 22 Sept and got exactly that. These are matched first so the complaint can name what
 * they actually pasted.
 */
const WRONG_LINK_KINDS = [
  [/\/document\/d\//, 'a Google Doc'],
  [/\/presentation\/d\//, 'a Google Slides deck'],
  [/\/forms\/d\//, 'a Google Form'],
  [/\/file\/d\//, 'a file stored in Drive (an upload, not a Google Sheet)'],
];

/**
 * Accepts what a person will actually paste: a full edit URL, a sharing URL, or the bare
 * id. Only `/spreadsheets/d/` counts as a link.
 */
function parseFileId(raw) {
  const s = String(raw === null || raw === undefined ? '' : raw).trim();
  if (!s) return null;
  for (const pair of WRONG_LINK_KINDS) if (pair[0].test(s)) return null;
  const fromUrl = /\/spreadsheets\/d\/([a-zA-Z0-9_-]{20,})/.exec(s);
  if (fromUrl) return fromUrl[1];
  if (/^[a-zA-Z0-9_-]{20,}$/.test(s)) return s;
  return null;
}

/** null when the link is usable, otherwise the sentence to show the person. */
function describeLinkProblem(raw) {
  const s = String(raw === null || raw === undefined ? '' : raw).trim();
  if (!s) return 'No link was given. Paste the link to the quotation Google Sheet.';
  for (const pair of WRONG_LINK_KINDS) {
    if (pair[0].test(s)) {
      return (
        `That link points at ${pair[1]}, not a Google Sheet. Open the quotation ` +
        `spreadsheet and copy the link from the address bar — a Sheet's link contains ` +
        `/spreadsheets/d/.`
      );
    }
  }
  if (!parseFileId(s)) {
    return (
      `That does not look like a Google Sheet link or id: ${JSON.stringify(s)}. ` +
      `Paste the full link from the address bar.`
    );
  }
  return null;
}

/**
 * Airtable filter for the rows whose link column mentions this file. Asking Airtable for
 * just those — usually one row — rather than the whole tracker keeps every other client's
 * contacts and costs out of the request and out of n8n's execution log. The id is
 * [A-Za-z0-9_-] only (parseFileId guarantees it), so it is safe inside the quotes.
 */
function trackerFilterFor(fileId, linkField) {
  return `FIND("${fileId}", {${linkField}})`;
}

// --- end link parsing -------------------------------------------------------

/** Airtable REST hands back { records: [{ id, fields }] }, possibly across pages. */
function collectAirtableRecords(pages) {
  const out = [];
  for (const page of [].concat(pages || [])) {
    const records = (page && page.records) || [];
    for (const r of records) out.push({ id: r.id, fields: r.fields || {} });
  }
  return out;
}

/**
 * The read nodes fail soft, so an HTTP error arrives here as `{ error: {...} }` instead of
 * ending the form on n8n's "Problem submitting response". Each is explained in words — and
 * each must be caught, or a failed read would look like an empty sheet or no linked row.
 */
function classifySheetResponse(resp, tab) {
  const err = errorText(resp);
  if (!err) return { values: (resp && resp.values) || [] };
  if (/unable to parse range/i.test(err)) {
    return {
      problem:
        `This spreadsheet has no "${tab}" tab, so it isn't a quotation file the sync ` +
        `knows how to read. Nothing was changed.`,
    };
  }
  if (/not found|requested entity/i.test(err)) {
    return {
      problem:
        `Couldn't find that spreadsheet. Check the link, and that the file is shared with ` +
        `the sync's Google account. Nothing was changed.`,
    };
  }
  if (/permission|forbidden|403/i.test(err)) {
    return {
      problem:
        `The sync's Google account isn't allowed to open that spreadsheet. Share it with ` +
        `view access, then try again. Nothing was changed.`,
    };
  }
  return {
    problem: `Couldn't read the quotation (Google said: ${err}). Nothing was changed — try again in a minute.`,
  };
}

function classifyTrackerPages(pages) {
  for (const page of [].concat(pages || [])) {
    const err = errorText(page);
    if (!err) continue;
    if (/unknown field/i.test(err)) {
      return {
        problem:
          `The tracker has no "${LINK_FIELD}" column, so the sync can't find the project's ` +
          `row. Add it as a URL column, then sync again. Nothing was changed.`,
      };
    }
    return { problem: `Couldn't read the tracker (Airtable said: ${err}). Nothing was changed.` };
  }
  return { records: collectAirtableRecords(pages) };
}

const TITLES = {
  preview: 'Preview — nothing was written',
  update: 'Updated',
  skip: 'No change needed',
  problem: "Couldn't sync this quotation",
};

/**
 * The title and body for the form's final screen. Kristine reads this, not the JSON.
 * In preview it says what *would* happen; everywhere else, what did.
 */
function summarize(state) {
  const { decision, extracted, preview } = state;
  const lines = [];

  if (decision.problem) {
    lines.push(decision.problem);
  } else {
    lines.push(decision.reason);
    if (decision.action === 'update') {
      lines.push('');
      lines.push(preview ? 'Would change:' : 'Changed:');
      for (const [k, v] of Object.entries(decision.fields)) {
        lines.push(`  ${k}: ${Array.isArray(v) ? v.map((x) => x.trim()).join(', ') : v}`);
      }
    }
  }

  const notes = [].concat(decision.notes || [], decision.warnings || []);
  if (notes.length) {
    lines.push('');
    lines.push('Worth checking:');
    for (const n of notes) lines.push(`  - ${n}`);
  }

  if (extracted && !decision.problem) {
    lines.push('');
    lines.push(`Approved cost taken from: ${extracted.meta.approvedCostSource}`);
  }

  const title = decision.problem ? TITLES.problem : preview ? TITLES.preview : TITLES[decision.action];
  const body = lines.join('\n');
  return { title, body, summary: `${title}\n\n${body}` };
}

/**
 * @param {object} ctx
 * @param {object} [ctx.sheetResponse]  Read Quotation's output (values, or an error payload)
 * @param {Array}  [ctx.sheetValues]    the values alone — for tests
 * @param {Array|object} [ctx.airtablePages]  Read Tracker's output page(s)
 * @param {string} ctx.fileId
 * @param {boolean} [ctx.preview]
 * @param {object} [ctx.options]
 */
function runDecision(ctx) {
  const preview = Boolean(ctx.preview);
  const tab = (ctx.options && ctx.options.quotationTab) || 'MAIN';

  const stopped = (problem) => {
    const text = summarize({ decision: { problem }, extracted: null, preview });
    return {
      action: 'skip',
      plannedAction: 'skip',
      problem,
      recordId: null,
      fields: {},
      reason: problem,
      notes: [],
      warnings: [],
      meta: null,
      title: text.title,
      body: text.body,
      summary: text.summary,
    };
  };

  const sheet =
    ctx.sheetResponse !== undefined
      ? classifySheetResponse(ctx.sheetResponse, tab)
      : { values: ctx.sheetValues || [] };
  if (sheet.problem) return stopped(sheet.problem);

  const tracker = classifyTrackerPages(ctx.airtablePages);
  if (tracker.problem) return stopped(tracker.problem);

  const extracted = extractQuotation(sheet.values, ctx.options);
  const decision = decideAction(extracted, {
    fileId: ctx.fileId,
    existingRecords: tracker.records,
  });

  const text = summarize({ decision, extracted, preview });

  return {
    action: preview ? 'preview' : decision.action,
    plannedAction: decision.action,
    problem: decision.problem || null,
    recordId: decision.recordId,
    fields: decision.fields,
    reason: decision.reason || decision.problem,
    notes: decision.notes,
    warnings: decision.warnings,
    meta: extracted.meta,
    title: text.title,
    body: text.body,
    summary: text.summary,
  };
}

/**
 * The Airtable call this run needs, or null when there is nothing to write. Only ever a
 * PATCH to the one linked row — there is no create.
 */
function buildWriteRequest(result, cfg) {
  if (!result || result.problem || result.action === 'preview') return null;
  if (result.plannedAction !== 'update' || !result.recordId) return null;
  return {
    method: 'PATCH',
    url: `https://api.airtable.com/v0/${cfg.baseId}/${encodeURIComponent(cfg.table)}/${result.recordId}`,
    body: { fields: result.fields, typecast: false },
  };
}

// --- result screen (sliced out verbatim into the Result node) ---------------

/** The message from an n8n fail-soft error payload, or null when the response is fine. */
function errorText(resp) {
  if (!resp || !resp.error) return null;
  if (typeof resp.error === 'string') return resp.error;
  return resp.error.description || resp.error.message || 'unknown error';
}

/**
 * Turn whatever ran into the one screen Kristine sees. "Was anything saved?" is the first
 * thing she will need to know, so every failure says.
 *
 * @param {object} p  outputs of Parse Request, Decide and Write Tracker — null for any
 *                    that did not run
 */
function composeResult(p) {
  const parse = p.parse || {};
  if (parse.ok === false) return { title: "That link won't work", message: parse.problem };

  const d = p.decided;
  if (!d) {
    return {
      title: 'Something went wrong',
      message:
        'The sync stopped before it could decide anything. Nothing was changed. ' +
        'Tell Tara — the details are in n8n.',
    };
  }

  const writeErr = errorText(p.written);
  if (writeErr) {
    return {
      title: 'Airtable refused the change',
      message: `Nothing was saved to the tracker. Safe to try again.\n\nAirtable said: ${writeErr}`,
    };
  }

  return { title: d.title, message: d.body };
}

// --- end result screen ------------------------------------------------------

// --- n8n adapter -----------------------------------------------------------
const input = $('Parse Request').first().json;

// Both read nodes fail soft: an HTTP error arrives as { error: ... } rather than stopping
// the run. runDecision classifies each, so a failed read is explained on the result
// screen instead of being mistaken for an empty sheet or no linked row.
const result = runDecision({
  sheetResponse: $('Read Quotation').first().json,
  airtablePages: $('Read Tracker').all().map(function (item) { return item.json; }),
  fileId: input.fileId,
  preview: input.preview,
  options: { quotationTab: input.config.quotationTab }
});

const write = buildWriteRequest(result, {
  baseId: input.config.airtableBaseId,
  table: input.config.airtableTable
});

return [{ json: Object.assign({}, result, { needsWrite: Boolean(write), write: write || {} }) }];

